package cpamp

import (
	"context"
	"fmt"

	"slices"
	"sort"
	"strings"
)

const UnknownAPIKey = "unattributed"

// The original ledger omitted API-key identity. Preserve it additively, using
// the immutable event hash, never numeric IDs that can be reused after imports.
// The read fallback below remains correct throughout the bounded backfill.
const keyJoins = ` LEFT JOIN analytics_event_keys k ON k.event_hash=a.event_hash
LEFT JOIN usage_events u ON u.event_hash=a.event_hash AND k.event_hash IS NULL `
const keyValue = `coalesce(k.api_key_hash,json_extract(a.payload,'$.api_key_hash'),u.api_key_hash,'')`

func (s *Service) apiKeys(ctx context.Context, through int64) ([]APIKey, error) {
	aliases, err := s.store.LoadAPIKeyAliases(ctx)
	if err != nil {
		return nil, err
	}
	names := map[string]string{}
	groups := map[string]string{}
	for _, a := range aliases {
		hashes := append([]string{a.APIKeyHash}, a.PreviousAPIKeyHashes...)
		sort.Strings(hashes)
		id := a.APIKeyHash
		if len(hashes) > 1 {

			id = "keys:" + strings.Join(hashes, ",")
		}
		names[id] = a.Alias
		for _, hash := range hashes {
			groups[hash] = id
		}
	}

	seen := map[string]bool{}
	read := func(query string, args ...any) error {
		rows, err := s.db.QueryContext(ctx, query, args...)
		if err != nil {
			return err
		}
		defer rows.Close()
		for rows.Next() {
			var hash string
			if err = rows.Scan(&hash); err != nil {
				return err
			}
			if group := groups[hash]; group != "" {
				hash = group
			}
			seen[hash] = true
		}
		return rows.Err()
	}
	cursor := s.cursor(ctx, "event_keys")
	if err = read(`SELECT DISTINCT k.api_key_hash FROM analytics_event_keys k JOIN analytics_events a ON a.event_hash=k.event_hash WHERE a.rowid<=? AND a.event_id<=?`, cursor, through); err != nil {
		return nil, err
	}
	if err = read(`SELECT DISTINCT `+keyValue+` FROM analytics_events a `+keyJoins+` WHERE a.rowid>? AND a.event_id<=?`, cursor, through); err != nil {
		return nil, err
	}
	hashes := make([]string, 0, len(seen))
	for hash := range seen {
		hashes = append(hashes, hash)
	}
	sort.Strings(hashes)
	out := []APIKey{}
	for _, hash := range hashes {
		id, label := hash, names[hash]
		if hash == "" {
			id, label = UnknownAPIKey, "Unattributed requests"
		} else if label == "" {
			label = fmt.Sprintf("Key %s", hash[:min(12, len(hash))])
		}
		out = append(out, APIKey{ID: id, Label: label})
	}
	return out, nil
}

func keyMatches(e Event, key string) bool {
	return key == "" || slices.Contains(apiKeyHashes(key), e.APIKeyHash)
}

func apiKeyHashes(key string) []string {
	if key == UnknownAPIKey {
		return []string{""}
	}
	if strings.HasPrefix(key, "keys:") {
		return strings.Split(strings.TrimPrefix(key, "keys:"), ",")
	}
	return []string{key}
}
func inWindow(e Event, w Window) bool {
	return w.Kind == "ledger" || (e.Started >= w.Start && e.Started < w.AttributionEnd && matches(e, w.Scope, w.Models))
}

// Always derive quotas and calibration from ALL account events. A client key
// selects a contribution to that shared pool, never a separate denominator.
func filterWindow(w Window, events []Event, key string) Window {
	if key == "" {
		return w
	}
	w.APIKeyFilter = key
	w.SharedUsage = &UsageTotals{Tokens: w.Tokens, Requests: w.Requests, CostNano: w.CostNano}
	w.Tokens = Tokens{}
	w.Requests = 0
	w.CostNano = 0
	w.Failed = 0
	w.Unpriced = 0
	w.Straddling = 0
	w.ClockSkew = 0
	for _, e := range events {
		if !keyMatches(e, key) || !inWindow(e, w) {
			continue
		}
		w.Requests++
		addTokens(&w.Tokens, e.Tokens)
		if e.CostNano == nil {
			w.Unpriced++
		} else {
			w.CostNano += *e.CostNano
		}
		if e.Failed {
			w.Failed++
		}
		if w.Kind != "ledger" {
			if e.Completed >= w.Reset {
				w.Straddling++
			}
			if e.HeaderTime > 0 && (e.HeaderTime < e.Started-5000 || e.HeaderTime > e.Completed+5000) {
				w.ClockSkew++
			}

		}
	}
	w.Notes = append(append([]string(nil), w.Notes...), "Tokens, requests and cost are filtered by client API key. Quota percentages, calibration and capacity estimates describe the shared account pool across all keys and may include external usage.")
	return w
}

func optionalKey(keys []string) string {
	if len(keys) > 0 {
		return keys[0]
	}
	return ""
}
